// @FIGURE_CODE_BEGIN
(function () {
  var NAVY = '#1F4E79', ORANGE = '#E8601C', GHOST = '#F0A882', TXT = '#152a45';
  var W = 620, H = 200;

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);
  var root = draw.group();

  var U = { x: 150, y: 0 }, V = { x: 58, y: -82 };
  var panels = [
    { key: 'L', A: { x: 30, y: 165 }, kind: 'sum' },
    { key: 'R', A: { x: 330, y: 165 }, kind: 'diff' }
  ];

  var STEPNAMES = ['draw u', 'attach v', 'complete parallelogram', 'reveal resultant'];
  var state = { op: 'add', step: 3, guided: false, selected: null, focus: null };

  /* ---------- small geometry / drawing helpers ---------- */
  function addv(a, b, c) { var r = { x: a.x + b.x, y: a.y + b.y }; if (c) { r.x += c.x; r.y += c.y; } return r; }
  function lerp(a, b, t) { return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t }; }
  function ang(s, e) { return Math.atan2(e.y - s.y, e.x - s.x); }

  function arrowHead(g, tip, a, color, s) {
    var c = Math.cos(a), si = Math.sin(a);
    function tp(px, py) { return [tip.x + px * c - py * si, tip.y + px * si + py * c]; }
    return g.polygon([tp(0, 0), tp(-s, -s * 0.46), tp(-s * 0.66, 0), tp(-s, s * 0.46)])
      .fill(color).stroke({ color: color, width: 0.6, linejoin: 'round' });
  }

  function label(g, x, y, txt, size, color) {
    var t = g.plain(txt)
      .font({ family: 'Georgia, "Times New Roman", serif', size: size || 15, style: 'italic', weight: 'bold' })
      .fill(color || TXT);
    t.attr({ x: x, y: y, 'text-anchor': 'middle' });
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.4, 'stroke-linejoin': 'round' });
    return t;
  }

  function hitLine(g, s, e, tip, onClick) {
    var l = g.line(s.x, s.y, e.x, e.y).stroke({ color: '#ffffff', width: 12, opacity: 0, linecap: 'round' });
    l.css('cursor', 'pointer');
    l.on('mousemove', function (ev) { showTooltip(tip, ev); });
    l.on('mouseleave', hideTooltip);
    if (onClick) l.on('click', function () { hideTooltip(); onClick(); });
    return l;
  }

  /* ---------- state helpers ---------- */
  function activePanel() { return state.focus || (state.op === 'add' ? 'L' : 'R'); }

  function selectDiag(panelKey, kind) {
    state.focus = panelKey;
    state.selected = { panel: panelKey, kind: kind };
    state.op = (kind === 'sum') ? 'add' : 'sub';
    state.guided = true;
    state.step = 3;
    demoIdx = -1;
    syncUI();
    render();
