    state.focus = panelKey;
    state.selected = { panel: panelKey, kind: kind };
    state.op = (kind === 'sum') ? 'add' : 'sub';
    state.guided = true;
    state.step = 3;
    demoIdx = -1;
    syncUI();
    render();
    if (kind === 'sum') {
      showPopup('Diagonal u + v',
        'This diagonal runs from the common tail to the opposite corner. Its two generating edges are highlighted: u along the bottom and v attached at the head of u. Travelling u-then-v (or v-then-u) reaches the same corner, so that corner is the sum.');
    } else {
      showPopup('Diagonal u − v',
        'The other diagonal of the very same parallelogram is the difference. Its generating edges are u along the top and the reversed vector −v pointing down-right. Subtracting v is simply adding the reverse of v, head to tail.');
    }
    setNarration('Selected the ' + (kind === 'sum' ? 'u + v' : 'u − v') +
      ' diagonal: its two generating edges are orange, the other parallelogram is dimmed.');
  }

  /* ---------- panel drawing ---------- */
  function drawPanel(p, ap) {
    var A = p.A, B = addv(A, U), C = addv(A, U, V), D = addv(A, V);
    var isA = (p.key === ap);
    var emph = state.guided && isA;
    var faded = state.guided && !isA;
    var kind = (isA && state.selected) ? state.selected.kind : p.kind;
    var step = emph ? state.step : 3;

    var g = root.group();
    if (faded) g.opacity(0.15);

    /* outline */
    if (step >= 2) {
      g.polygon([[A.x, A.y], [B.x, B.y], [C.x, C.y], [D.x, D.y]])
        .fill('none').stroke({ color: NAVY, width: 3, linejoin: 'round' });
    }

    /* diagonals (thin navy) */
    if (step >= 2) {
      [{ k: 'sum', s: A, e: C }, { k: 'diff', s: D, e: B }].forEach(function (d) {
        var isRes = (d.k === kind) && emph && step >= 3;
        g.line(d.s.x, d.s.y, d.e.x, d.e.y)
          .stroke({ color: isRes ? ORANGE : NAVY, width: isRes ? 3 : 1.2, linecap: 'round' });
        hitLine(g, d.s, d.e,
          (d.k === 'sum' ? 'Diagonal u + v' : 'Diagonal u − v') + ' — click to light up its two generating edges',
          function () { selectDiag(p.key, d.k); });
      });
    }

    /* the resultant arrowhead + label */
    var rS = (kind === 'sum') ? A : D, rE = (kind === 'sum') ? C : B;
    if (step >= 3) {
      var tip = lerp(rS, rE, 0.95);
      if (!emph) {
        var q = lerp(rS, rE, 0.78);
        g.line(q.x, q.y, tip.x, tip.y).stroke({ color: ORANGE, width: 3 });
      }
      arrowHead(g, tip, ang(rS, rE), ORANGE, emph ? 10 : 9);
    }

    /* active vectors u and v (orange) */
    var uS, uE, vS, vE;
    if (kind === 'sum') { uS = A; uE = B; vS = B; vE = C; } else { uS = D; uE = C; vS = C; vE = B; }

    function vec(s, e, t, name, tipTxt) {
      var tip = lerp(s, e, t);
      if (emph) {
        g.line(s.x, s.y, e.x, e.y).stroke({ color: ORANGE, width: 3.2, linecap: 'round' });
      } else {
        var q = lerp(s, e, t - 0.22);
        g.line(q.x, q.y, tip.x, tip.y).stroke({ color: ORANGE, width: 3.2 });
      }
      arrowHead(g, tip, ang(s, e), ORANGE, 9);
      hitLine(g, s, e, tipTxt, null);
    }

    if (step >= 0) vec(uS, uE, 0.74, 'u', 'u — the first vector, drawn from the common tail');
    if (step >= 1) vec(vS, vE, 0.84, 'v',
      kind === 'sum' ? 'v — attached head-to-tail at the head of u'
        : '−v — v turned through 180°, attached at the head of u');

    /* ghost of the un-reversed v */
    if (kind === 'diff' && emph && step >= 1) {
      var len = Math.sqrt(V.x * V.x + V.y * V.y);
      var px = (V.y / len) * 7, py = (-V.x / len) * 7;
      var gs = { x: B.x + px, y: B.y + py }, ge = { x: C.x + px, y: C.y + py };
      g.line(gs.x, gs.y, ge.x, ge.y).stroke({ color: GHOST, width: 2, dasharray: '5,4', linecap: 'round' });
      arrowHead(g, lerp(gs, ge, 0.98), ang(gs, ge), GHOST, 7);
      var gm = lerp(gs, ge, 0.45);
      label(g, gm.x + px * 1.6, gm.y + py * 1.6, 'v', 12, GHOST);
    }

    /* ---- labels last, on top ---- */
    if (step >= 0) {
      if (kind === 'sum') { var lu = lerp(uS, uE, 0.40); label(g, lu.x, lu.y + 18, 'u', 15); }
      else { var lu2 = lerp(uS, uE, 0.55); label(g, lu2.x, lu2.y - 11, 'u', 15); }
    }
    if (step >= 1) {
      var lv = lerp(vS, vE, 0.5);
      label(g, lv.x + 18, lv.y + 13, kind === 'sum' ? 'v' : '−v', 15);
    }
    if (kind === 'diff' && step >= 2) {
      label(g, A.x + 62, A.y + 18, 'u', 15);
    }
    if (step >= 3) {
      var lp = lerp(rS, rE, kind === 'sum' ? 0.42 : 0.45);
      label(g, lp.x, lp.y - (kind === 'sum' ? 26 : 13), kind === 'sum' ? 'u + v' : 'u − v', 15);
    }
  }

  function render() {
    root.clear();
    var ap = activePanel();
    for (var i = 0; i < panels.length; i++) drawPanel(panels[i], ap);
  }

  /* ---------- controls ---------- */
  function syncUI() {
    var cb = document.getElementById('operationInput');
    if (cb) cb.checked = (state.op === 'sub');
    var sv = document.getElementById('constructionStepVal');
    if (sv) sv.textContent = STEPNAMES[state.step];
  }

  function setNarration(txt) {
    var n = document.getElementById('demoNarration');
    if (n) n.textContent = txt;
  }

  window.toggle_operation = function (on) {
    state.op = on ? 'sub' : 'add';
    state.selected = null;
    state.focus = null;
    state.guided = true;
    demoIdx = -1;
    syncUI(); render();
    setNarration(on
      ? 'v is reversed into −v: same parallelogram, same u, but the resultant is now the descending diagonal u − v.'
      : 'v points up-right again: the resultant is the rising diagonal u + v.');
  };

  window.trigger_constructionStep = function () {
    state.guided = true;
    state.selected = null;
    state.step = (state.step + 1) % 4;
    demoIdx = -1;
    syncUI(); render();
    var msgs = [
      'Only u is drawn from the common tail.',
      'The second vector is attached head-to-tail at the head of u.',
      'Copies of the two vectors close the parallelogram — both routes end at the same corner.',
      'The diagonal from the common tail is the resultant.'
    ];
    setNarration(msgs[state.step]);
  };

  window.trigger_reset = function () {
    demoIdx = 0; applyStep(0);
  };

  /* ---------- demo player ---------- */
  var steps = [
    {
      t: 'Textbook view',
      n: 'Both parallelograms as printed: the left diagonal is the sum u + v, the right diagonal is the difference u − v. Click a diagonal, or step through the construction.',
      s: { guided: false, op: 'add', step: 3 }
    },
    {
      t: 'Start with u',
      n: 'A single vector u is drawn from the origin along the bottom edge, orange arrowhead pointing right. Nothing else exists yet.',
      s: { guided: true, op: 'add', step: 0 }
    },
    {
      t: 'Attach v head to tail',
      n: 'v is placed with its tail at the head of u, slanting up and to the right. The two vectors now form a bent path from the origin.',
      s: { guided: true, op: 'add', step: 1 }
    },
    {
      t: 'Close the parallelogram',
      n: 'Copies of u and v complete the figure, so the same endpoint is reached by going u-then-v or v-then-u.',
      s: { guided: true, op: 'add', step: 2 }
    },
    {
      t: 'The sum is the long diagonal',
      n: 'The diagonal from the common tail to the opposite corner is highlighted in orange and labeled u + v.',
      s: { guided: true, op: 'add', step: 3 }
    },
    {
      t: 'Reverse v into −v',
      n: 'Flipping the toggle turns v around: the arrowhead on the slanted edge now points down and to the right, labeled −v (the dashed ghost shows the old v), while u is unchanged.',
      s: { guided: true, op: 'sub', step: 1 }
    },
    {
      t: 'The difference is the other diagonal',
      n: 'Head-to-tail with −v, the resultant becomes the descending diagonal labeled u − v — the same parallelogram, the other diagonal.',
      s: { guided: true, op: 'sub', step: 3 }
    }
  ];
  var demoIdx = 0;

  function applyStep(i) {
    demoIdx = i;
    var st = steps[i];
    state.guided = st.s.guided;
    state.op = st.s.op;
    state.step = st.s.step;
    state.selected = null;
    state.focus = null;
    syncUI();
    render();
    setNarration(st.n);
    var lbl = document.getElementById('stepLabel');
    if (lbl) lbl.textContent = i + ' / ' + (steps.length - 1) + ' · ' + st.t;
  }

  window.nextStep = function () { applyStep(Math.min(steps.length - 1, (demoIdx < 0 ? 0 : demoIdx) + 1)); };
  window.prevStep = function () { applyStep(Math.max(0, (demoIdx < 0 ? 1 : demoIdx) - 1)); };

  /* ---------- init ---------- */
  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

