// @FIGURE_CODE_BEGIN
(function () {
  var NAVY = '#1F4E79', ORANGE = '#E8601C', GHOST = '#F0A882', TXT = '#152a45';

  var container = document.getElementById('container');
  var draw = SVG().addTo(container).size('100%', '100%');
  var root = draw.group();

  /* shape vectors (world units) */
  var U = { x: 210, y: 0 }, V = { x: 84, y: -118 };
  var SW = U.x + V.x, SH = -V.y;            // 294 x 118

  var panels = [
    { key: 'L', kind: 'sum', A: { x: 0, y: 0 } },
    { key: 'R', kind: 'diff', A: { x: 0, y: 0 } }
  ];

  var K = 1;                                 // world units per rendered pixel
  function PX(v) { return v * K; }

  var STEPNAMES = ['draw u', 'attach v', 'complete parallelogram', 'reveal resultant'];
  var state = { op: 'add', step: 3, guided: false, selected: null, focus: null };

  /* ---------- geometry helpers ---------- */
  function addv(a, b, c) { var r = { x: a.x + b.x, y: a.y + b.y }; if (c) { r.x += c.x; r.y += c.y; } return r; }
  function lerp(a, b, t) { return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t }; }
  function ang(s, e) { return Math.atan2(e.y - s.y, e.x - s.x); }

  function arrowHead(g, tip, a, color, s) {
    var c = Math.cos(a), si = Math.sin(a);
    function tp(px, py) { return [tip.x + px * c - py * si, tip.y + px * si + py * c]; }
    return g.polygon([tp(0, 0), tp(-s, -s * 0.46), tp(-s * 0.64, 0), tp(-s, s * 0.46)])
      .fill(color).stroke({ color: color, width: s * 0.06, linejoin: 'round' });
  }

  function label(g, x, y, txt, px, color, weight) {
    var t = g.plain(txt)
      .font({
        family: 'Georgia, "Times New Roman", serif',
        size: PX(px), style: 'italic', weight: weight || 'bold'
      })
      .fill(color || TXT);
    t.attr({ x: x, y: y, 'text-anchor': 'middle' });
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': PX(3.6), 'stroke-linejoin': 'round' });
    return t;
  }

  function hitLine(g, s, e, tip, onClick) {
    var l = g.line(s.x, s.y, e.x, e.y).stroke({ color: '#fff', width: PX(13), opacity: 0, linecap: 'round' });
    l.css('cursor', onClick ? 'pointer' : 'help');
    l.on('mousemove', function (ev) { showTooltip(tip, ev); });
    l.on('mouseleave', hideTooltip);
    if (onClick) l.on('click', function () { hideTooltip(); onClick(); });
    return l;
  }

  /* ---------- state helpers ---------- */
  function activePanel() { return state.focus || (state.op === 'add' ? 'L' : 'R'); }

  function selectDiag(panelKey, kind) {
    state.focus = panelKey;
    state.selected = { panel: panelKey, kind: kind };
    state.op = (kind === 'sum') ? 'add' : 'sub';
    state.guided = true;
    state.step = 3;
    demoIdx = -1;
    syncUI(); render();
    if (kind === 'sum') {
      showPopup('Diagonal u + v',
        'This diagonal runs from the common tail to the opposite corner. Its two generating edges are highlighted: u along the bottom and v attached at the head of u. Travelling u-then-v (or v-then-u) reaches the same corner, so that corner is the sum.');
    } else {
      showPopup('Diagonal u − v',
        'The other diagonal of the very same parallelogram is the difference. Its generating edges are u along the top and the reversed vector −v pointing down-right. Subtracting v is simply adding the reverse of v, head to tail.');
    }
    setNarration('Selected the ' + (kind === 'sum' ? 'u + v' : 'u − v') +
      ' diagonal: its two generating edges are orange, the other parallelogram is faded but still outlined.');
  }

  /* ---------- panel drawing ---------- */
  function drawPanel(p, ap) {
    var A = p.A, B = addv(A, U), C = addv(A, U, V), D = addv(A, V);
    var isA = (p.key === ap);
    var emph = state.guided && isA;
    var faded = state.guided && !isA;
    var kind = (isA && state.selected) ? state.selected.kind : p.kind;
    var step = emph ? state.step : 3;

    var g = root.group();
    if (faded) g.opacity(0.38);

    /* outline */
    if (step >= 2) {
      g.polygon([[A.x, A.y], [B.x, B.y], [C.x, C.y], [D.x, D.y]])
        .fill('none').stroke({ color: NAVY, width: PX(3.2), linejoin: 'round' });
    }

    /* diagonals (thin navy; active one orange) */
    if (step >= 2) {
      [{ k: 'sum', s: A, e: C }, { k: 'diff', s: D, e: B }].forEach(function (d) {
        var isRes = (d.k === kind) && emph && step >= 3;
        g.line(d.s.x, d.s.y, d.e.x, d.e.y)
          .stroke({ color: isRes ? ORANGE : NAVY, width: PX(isRes ? 3.2 : 1.2), linecap: 'round' });
        hitLine(g, d.s, d.e,
          (d.k === 'sum' ? 'Diagonal u + v' : 'Diagonal u − v') + ' — click to light up its two generating edges',
          function () { selectDiag(p.key, d.k); });
      });
    }

    /* resultant arrowhead */
    var rS = (kind === 'sum') ? A : D, rE = (kind === 'sum') ? C : B;
    var rT = (kind === 'sum') ? 0.97 : 0.90;      // pull the difference head back off the corner
    if (step >= 3) {
      var tip = lerp(rS, rE, rT);
      if (!emph) {
        var q = lerp(rS, rE, rT - 0.20);
        g.line(q.x, q.y, tip.x, tip.y).stroke({ color: ORANGE, width: PX(3.2), linecap: 'round' });
      }
      arrowHead(g, tip, ang(rS, rE), ORANGE, PX(11));
    }

    /* active edge vectors */
    var uS, uE, vS, vE, vT;
    if (kind === 'sum') { uS = A; uE = B; vS = B; vE = C; vT = 0.84; }
    else { uS = D; uE = C; vS = C; vE = B; vT = 0.52; }   // mid-edge head keeps clear of the diagonal head

    function vec(s, e, t, tipTxt) {
      var tip = lerp(s, e, t);
      if (emph) {
        g.line(s.x, s.y, e.x, e.y).stroke({ color: ORANGE, width: PX(3.2), linecap: 'round' });
      } else {
        var q = lerp(s, e, Math.max(0, t - 0.24));
        g.line(q.x, q.y, tip.x, tip.y).stroke({ color: ORANGE, width: PX(3.2), linecap: 'round' });
      }
      arrowHead(g, tip, ang(s, e), ORANGE, PX(10));
      hitLine(g, s, e, tipTxt, null);
    }

    if (step >= 0) vec(uS, uE, kind === 'sum' ? 0.74 : 0.86, 'u — the first vector, drawn from the common tail');
    if (step >= 1) vec(vS, vE, vT, kind === 'sum'
      ? 'v — attached head-to-tail at the head of u'
      : '−v — v turned through 180°, attached at the head of u');

    /* dashed ghost of the un-reversed v */
    if (kind === 'diff' && emph && step >= 1) {
      var len = Math.sqrt(V.x * V.x + V.y * V.y);
