        .fill('none').stroke({ color: NAVY, width: PX(3.2), linejoin: 'round' });
    }

    /* diagonals (thin navy; active one orange) */
    if (step >= 2) {
      [{ k: 'sum', s: A, e: C }, { k: 'diff', s: D, e: B }].forEach(function (d) {
        var isRes = (d.k === kind) && emph && step >= 3;
        g.line(d.s.x, d.s.y, d.e.x, d.e.y)
          .stroke({ color: isRes ? ORANGE : NAVY, width: PX(isRes ? 3.2 : 1.2), linecap: 'round' });
        hitLine(g, d.s, d.e,
          (d.k === 'sum' ? 'Diagonal u + v' : 'Diagonal u − v') + ' — click to light up its two generating edges',
          function () { selectDiag(p.key, d.k); });
      });
    }

    /* resultant arrowhead */
    var rS = (kind === 'sum') ? A : D, rE = (kind === 'sum') ? C : B;
    var rT = (kind === 'sum') ? 0.97 : 0.90;      // pull the difference head back off the corner
    if (step >= 3) {
      var tip = lerp(rS, rE, rT);
      if (!emph) {
        var q = lerp(rS, rE, rT - 0.20);
        g.line(q.x, q.y, tip.x, tip.y).stroke({ color: ORANGE, width: PX(3.2), linecap: 'round' });
      }
      arrowHead(g, tip, ang(rS, rE), ORANGE, PX(11));
    }

    /* active edge vectors */
    var uS, uE, vS, vE, vT;
    if (kind === 'sum') { uS = A; uE = B; vS = B; vE = C; vT = 0.84; }
    else { uS = D; uE = C; vS = C; vE = B; vT = 0.52; }   // mid-edge head keeps clear of the diagonal head

    function vec(s, e, t, tipTxt) {
      var tip = lerp(s, e, t);
      if (emph) {
        g.line(s.x, s.y, e.x, e.y).stroke({ color: ORANGE, width: PX(3.2), linecap: 'round' });
      } else {
        var q = lerp(s, e, Math.max(0, t - 0.24));
        g.line(q.x, q.y, tip.x, tip.y).stroke({ color: ORANGE, width: PX(3.2), linecap: 'round' });
      }
      arrowHead(g, tip, ang(s, e), ORANGE, PX(10));
      hitLine(g, s, e, tipTxt, null);
    }

    if (step >= 0) vec(uS, uE, kind === 'sum' ? 0.74 : 0.86, 'u — the first vector, drawn from the common tail');
    if (step >= 1) vec(vS, vE, vT, kind === 'sum'
      ? 'v — attached head-to-tail at the head of u'
      : '−v — v turned through 180°, attached at the head of u');

    /* dashed ghost of the un-reversed v */
    if (kind === 'diff' && emph && step >= 1) {
      var len = Math.sqrt(V.x * V.x + V.y * V.y);
      var px = (V.y / len) * PX(9), py = (-V.x / len) * PX(9);
      var gs = { x: B.x + px, y: B.y + py }, ge = { x: C.x + px, y: C.y + py };
      g.line(gs.x, gs.y, ge.x, ge.y)
        .stroke({ color: GHOST, width: PX(2), dasharray: PX(5) + ',' + PX(4), linecap: 'round' });
      arrowHead(g, lerp(gs, ge, 0.97), ang(gs, ge), GHOST, PX(8));
      var gm = lerp(gs, ge, 0.42);
      label(g, gm.x + px * 1.7, gm.y + py * 1.7, 'v', 14, GHOST);
    }

    /* common tail dot */
    if (emph) g.circle(PX(5.4)).center(A.x, A.y).fill(NAVY);

    /* ---- labels last, on top ---- */
    if (step >= 0) {
      if (kind === 'sum') {
        var lu = lerp(uS, uE, 0.38); label(g, lu.x, lu.y + PX(21), 'u', 19);
      } else {
        var lu2 = lerp(uS, uE, 0.62); label(g, lu2.x, lu2.y - PX(13), 'u', 19);
      }
    }
    if (step >= 1) {
      var lv = lerp(vS, vE, kind === 'sum' ? 0.52 : 0.62);
      label(g, lv.x + PX(kind === 'sum' ? 20 : 26), lv.y + PX(6), kind === 'sum' ? 'v' : '−v', 19);
    }
    if (kind === 'diff' && step >= 2) {
      var lb = lerp(A, B, 0.42);
      label(g, lb.x, lb.y + PX(22), 'u', 19);
    }
    if (step >= 3) {
      var lp = lerp(rS, rE, kind === 'sum' ? 0.40 : 0.40);
      label(g, lp.x + PX(kind === 'sum' ? 0 : -2), lp.y - PX(kind === 'sum' ? 13 : 11),
        kind === 'sum' ? 'u + v' : 'u − v', 24);
    }
  }

  function render() {
    root.clear();
    var ap = activePanel();
    for (var i = 0; i < panels.length; i++) drawPanel(panels[i], ap);
  }

  /* ---------- responsive layout: fill the frame ---------- */
  function innerSize() {
    var st = getComputedStyle(container);
    var px = (parseFloat(st.paddingLeft) || 0) + (parseFloat(st.paddingRight) || 0);
    var py = (parseFloat(st.paddingTop) || 0) + (parseFloat(st.paddingBottom) || 0);
    return { w: Math.max(80, container.clientWidth - px), h: Math.max(80, container.clientHeight - py) };
  }

  function layout(sz) {
    sz = sz || innerSize();
    var aspect = sz.w / sz.h;
    var mL = 46, mT = 50, mB = 48, VBW, VBH;

    if (aspect >= 1.75) {                       // side-by-side, like the printed figure
      var gapX = 84;
      panels[0].A = { x: mL, y: mT + SH };
      panels[1].A = { x: mL + SW + gapX, y: mT + SH };
      VBW = mL + SW * 2 + gapX + mL;
      VBH = mT + SH + mB;
    } else {                                    // stacked, so the shapes stay large in a tall frame
      var gapY = 84;
      panels[0].A = { x: mL, y: mT + SH };
      panels[1].A = { x: mL, y: mT + SH + gapY + SH };
      VBW = mL + SW + mL;
      VBH = mT + SH + gapY + SH + mB;
    }

    draw.viewbox(0, 0, VBW, VBH);
    var s = Math.min(sz.w / VBW, sz.h / VBH);   // rendered px per world unit
    K = 1 / Math.max(0.12, s);                  // world units per rendered px
    render();
  }

  document.addEventListener('fig-resize', function (e) {
    layout({ w: e.detail.width || innerSize().w, h: e.detail.height || innerSize().h });
  });

  /* ---------- controls ---------- */
  function syncUI() {
    var cb = document.getElementById('operationInput');
    if (cb) cb.checked = (state.op === 'sub');
    var sv = document.getElementById('constructionStepVal');
    if (sv) sv.textContent = STEPNAMES[state.step];
  }

  function setNarration(txt) {
    var n = document.getElementById('demoNarration');
    if (n) n.textContent = txt;
  }

  window.toggle_operation = function (on) {
    state.op = on ? 'sub' : 'add';
    state.selected = null; state.focus = null; state.guided = true;
    demoIdx = -1;
    syncUI(); render();
    setNarration(on
      ? 'v is reversed into −v: same parallelogram, same u, but the resultant is now the descending diagonal u − v.'
      : 'v points up-right again: the resultant is the rising diagonal u + v.');
  };

  window.trigger_constructionStep = function () {
    state.guided = true; state.selected = null;
    state.step = (state.step + 1) % 4;
    demoIdx = -1;
    syncUI(); render();
    var msgs = [
      'Only u is drawn from the common tail.',
      'The second vector is attached head-to-tail at the head of u.',
      'Copies of the two vectors close the parallelogram — both routes end at the same corner.',
      'The diagonal from the common tail is the resultant.'
    ];
    setNarration(msgs[state.step]);
  };

  window.trigger_reset = function () { applyStep(0); };

  /* ---------- demo player ---------- */
  var steps = [
    {
      t: 'Textbook view',
      n: 'Both parallelograms as printed: the left diagonal is the sum u + v, the right diagonal is the difference u − v. Click a diagonal, or step through the construction.',
      s: { guided: false, op: 'add', step: 3 }
    },
    {
      t: 'Start with u',
      n: 'A single vector u is drawn from the common tail along the bottom edge, orange arrowhead pointing right. Nothing else exists yet.',
      s: { guided: true, op: 'add', step: 0 }
    },
    {
      t: 'Attach v head to tail',
      n: 'v is placed with its tail at the head of u, slanting up and to the right. The two vectors now form a bent path from the origin.',
      s: { guided: true, op: 'add', step: 1 }
    },
    {
      t: 'Close the parallelogram',
      n: 'Copies of u and v complete the figure, so the same endpoint is reached by going u-then-v or v-then-u.',
      s: { guided: true, op: 'add', step: 2 }
    },
    {
      t: 'The sum is the long diagonal',
      n: 'The diagonal from the common tail to the opposite corner is highlighted in orange and labeled u + v.',
      s: { guided: true, op: 'add', step: 3 }
    },
    {
      t: 'Reverse v into −v',
      n: 'Flipping the toggle turns v around: the arrowhead on the slanted edge now points down and to the right, labeled −v (the dashed ghost shows the old v), while u is unchanged.',
      s: { guided: true, op: 'sub', step: 1 }
    },
    {
      t: 'The difference is the other diagonal',
      n: 'Head-to-tail with −v, the resultant becomes the descending diagonal labeled u − v — the same parallelogram, the other diagonal.',
      s: { guided: true, op: 'sub', step: 3 }
    }
  ];
  var demoIdx = 0;

  function applyStep(i) {
    demoIdx = i;
    var st = steps[i];
    state.guided = st.s.guided; state.op = st.s.op; state.step = st.s.step;
    state.selected = null; state.focus = null;
    syncUI(); render(); setNarration(st.n);
    var lbl = document.getElementById('stepLabel');
    if (lbl) lbl.textContent = i + ' / ' + (steps.length - 1) + ' · ' + st.t;
  }

  window.nextStep = function () { applyStep(Math.min(steps.length - 1, (demoIdx < 0 ? 0 : demoIdx) + 1)); };
  window.prevStep = function () { applyStep(Math.max(0, (demoIdx < 0 ? 1 : demoIdx) - 1)); };

  /* ---------- init ---------- */
  layout();
  applyStep(0);
  setTimeout(function () { layout(); applyStep(demoIdx < 0 ? 0 : demoIdx); }, 60);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: In a parallelogram built from u and v, the two diagonals are the resultants u + v and u − v, so subtracting a vector is the same as adding its reverse.
KEY INSIGHT (what students should walk away understanding): One parallelogram holds both answers: its two diagonals are u + v and u − v, because subtracting v is just adding the reversed vector −v.
DEMO STEPS: 6 guided steps — implement the step player in #ui

