// @FIGURE_CODE_BEGIN
(function () {
  var NAVY = '#1F4E79', ORANGE = '#E8601C', GHOST = '#F0A882', TXT = '#14263f';

  var container = document.getElementById('container');
  var draw = SVG().addTo(container).size('100%', '100%');
  var root = draw.group();

  /* shape vectors (world units) — proportions taken from the printed figure */
  var U = { x: 210, y: 0 }, V = { x: 118, y: -108 };
  var SW = U.x + V.x, SH = -V.y;

  var panels = [
    { key: 'L', kind: 'sum', A: { x: 0, y: 0 } },
    { key: 'R', kind: 'diff', A: { x: 0, y: 0 } }
  ];

  var s = 1;                                  // rendered px per world unit

  /* size helpers: authored in world units, clamped so a tiny or huge frame
     still yields readable, non-oversized marks                              */
  function fw(base, lo, hi) {
    var r = base * s;
    if (r > hi) r = hi;
    if (r < lo) r = lo;
    return r / s;
  }
  function TS(base) { return fw(base, 8.5, 26); }    // text
  function LW(base) { return fw(base, 0.75, 5.2); }  // stroke width
  function AH(base) { return fw(base, 6, 19); }      // arrowhead

  var STEPNAMES = ['draw u', 'attach v', 'complete parallelogram', 'reveal resultant'];
  var state = { op: 'add', step: 3, guided: false, selected: null, focus: null };

  /* ---------- geometry helpers ---------- */
  function addv(a, b, c) { var r = { x: a.x + b.x, y: a.y + b.y }; if (c) { r.x += c.x; r.y += c.y; } return r; }
  function lerp(a, b, t) { return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t }; }
  function ang(a, b) { return Math.atan2(b.y - a.y, b.x - a.x); }
  function unit(a, b) {
    var dx = b.x - a.x, dy = b.y - a.y, L = Math.sqrt(dx * dx + dy * dy) || 1;
    return { x: dx / L, y: dy / L };
  }
  function rnorm(a, b) { var u = unit(a, b); return { x: u.y, y: -u.x }; }   // right-hand normal

  function arrowHead(g, tip, a, color, sz) {
    var c = Math.cos(a), si = Math.sin(a);
    function tp(px, py) { return [tip.x + px * c - py * si, tip.y + px * si + py * c]; }
    return g.polygon([tp(0, 0), tp(-sz, -sz * 0.44), tp(-sz * 0.62, 0), tp(-sz, sz * 0.44)])
      .fill(color).stroke({ color: color, width: sz * 0.06, linejoin: 'round' });
  }

  function label(g, x, y, txt, base, color) {
    var sz = TS(base);
    var t = g.plain(txt)
      .font({ family: 'Georgia, "Times New Roman", serif', size: sz, style: 'italic', weight: 'bold' })
      .fill(color || TXT);
    t.attr({ x: x, y: y + sz * 0.34, 'text-anchor': 'middle' });
    t.attr({
      'paint-order': 'stroke', stroke: '#ffffff',
      'stroke-width': sz * 0.24, 'stroke-linejoin': 'round'
    });
    return t;
  }

  function hitLine(g, a, b, tip, onClick) {
    var l = g.line(a.x, a.y, b.x, b.y)
      .stroke({ color: '#fff', width: fw(16, 8, 20), opacity: 0, linecap: 'round' });
    l.css('cursor', onClick ? 'pointer' : 'help');
    l.on('mousemove', function (ev) { showTooltip(tip, ev); });
    l.on('mouseleave', hideTooltip);
    if (onClick) l.on('click', function () { hideTooltip(); onClick(); });
    return l;
  }

  /* ---------- state helpers ---------- */
  function activePanel() { return state.focus || (state.op === 'add' ? 'L' : 'R'); }

  function selectDiag(panelKey, kind) {
    state.focus = panelKey;
    state.selected = { panel: panelKey, kind: kind };
    state.op = (kind === 'sum') ? 'add' : 'sub';
    state.guided = true;
    state.step = 3;
    demoIdx = -1;
    syncUI(); render();
    if (kind === 'sum') {
      showPopup('Diagonal u + v',
        'This diagonal runs from the common tail to the opposite corner. Its two generating edges are now orange: u along the bottom and v attached at the head of u. Travelling u-then-v (or v-then-u) reaches the same corner, so that corner is the sum.');
    } else {
      showPopup('Diagonal u − v',
        'The other diagonal of the very same parallelogram is the difference. Its generating edges are u along the top and the reversed vector −v pointing down-right. Subtracting v is simply adding the reverse of v, head to tail.');
    }
    setNarration('Selected the ' + (kind === 'sum' ? 'u + v' : 'u − v') +
      ' diagonal: its two generating edges are orange; the other parallelogram is faded but still outlined.');
  }

  /* ---------- panel drawing ---------- */
  function drawPanel(p, ap) {
    var A = p.A, B = addv(A, U), C = addv(A, U, V), D = addv(A, V);
    var isA = (p.key === ap);
    var emph = state.guided && isA;
    var faded = state.guided && !isA;
    var kind = (isA && state.selected) ? state.selected.kind : p.kind;
    var step = emph ? state.step : 3;

    var g = root.group();
    if (faded) g.opacity(0.3);

    /* ---- outline ---- */
    if (step >= 2) {
      g.polygon([[A.x, A.y], [B.x, B.y], [C.x, C.y], [D.x, D.y]])
        .fill('none').stroke({ color: NAVY, width: LW(3.4), linejoin: 'round' });
    }

    /* ---- thin navy diagonals ---- */
    var showDiag = (!emph) || step >= 3;
    if (showDiag) {
      [{ k: 'sum', a: A, b: C }, { k: 'diff', a: D, b: B }].forEach(function (d) {
        var hot = emph && (d.k === kind) && step >= 3;
        g.line(d.a.x, d.a.y, d.b.x, d.b.y)
          .stroke({ color: hot ? ORANGE : NAVY, width: LW(hot ? 3.4 : 1.15), linecap: 'round' });
        hitLine(g, d.a, d.b,
          (d.k === 'sum' ? 'Diagonal u + v' : 'Diagonal u − v') +
          ' — click to light up its two generating edges',
          function () { selectDiag(p.key, d.k); });
      });
    }

    /* ---- resultant arrowhead ----
       textbook view: only the sum diagonal carries an orange head (as printed) */
    var rS = (kind === 'sum') ? A : D, rE = (kind === 'sum') ? C : B;
    if (step >= 3 && (emph || kind === 'sum')) {
      var tEnd = emph ? ((kind === 'sum') ? 0.965 : 0.94) : 0.965;
      var tip = lerp(rS, rE, tEnd);
      if (!emph) {                                   // short orange lead-in only
        var q = lerp(rS, rE, tEnd - 0.17);
        g.line(q.x, q.y, tip.x, tip.y).stroke({ color: ORANGE, width: LW(3.4), linecap: 'round' });
      }
      arrowHead(g, tip, ang(rS, rE), ORANGE, AH(13));
    }

    /* ---- active edge vectors ---- */
    function vec(a, b, t0, t1, tipTxt) {
      var from = emph ? a : lerp(a, b, t0);
      var to = emph ? lerp(a, b, 0.975) : lerp(a, b, t1);
      g.line(from.x, from.y, to.x, to.y).stroke({ color: ORANGE, width: LW(3.4), linecap: 'round' });
      arrowHead(g, to, ang(a, b), ORANGE, AH(12));
      hitLine(g, a, b, tipTxt, null);
    }

    var uS, uE, vS, vE, uT0, uT1, vT0, vT1;
    if (kind === 'sum') {
      uS = A; uE = B; uT0 = 0.50; uT1 = 0.66;
      vS = B; vE = C; vT0 = 0.60; vT1 = 0.80;
    } else {
      uS = D; uE = C; uT0 = 0.62; uT1 = 0.80;
      vS = C; vE = B; vT0 = 0.30; vT1 = 0.50;
    }

    if (step >= 0) vec(uS, uE, uT0, uT1, 'u — the first vector, drawn from the common tail');
    if (step >= 1) vec(vS, vE, vT0, vT1, kind === 'sum'
      ? 'v — attached head-to-tail at the head of u'
      : '−v — v turned through 180°, attached at the head of u');

    /* ---- dashed ghost of the un-reversed v ---- */
    if (kind === 'diff' && emph && step >= 1) {
      var n = rnorm(B, C);
      var off = fw(13, 7, 16);
      var gs = { x: B.x + n.x * off, y: B.y + n.y * off };
      var ge = { x: C.x + n.x * off, y: C.y + n.y * off };
      g.line(gs.x, gs.y, ge.x, ge.y)
        .stroke({ color: GHOST, width: LW(1.9), dasharray: LW(5) + ',' + LW(4), linecap: 'round' });
      arrowHead(g, lerp(gs, ge, 0.96), ang(gs, ge), GHOST, AH(9));
      var gm = lerp(gs, ge, 0.34);
      label(g, gm.x + n.x * off * 1.5, gm.y + n.y * off * 1.5, 'v', 17, GHOST);
    }

    /* ---- common tail dot ---- */
    if (emph) {
      var tail = (kind === 'sum') ? A : D;
      g.circle(fw(6, 3, 8)).center(tail.x, tail.y).fill(NAVY);
    }

    /* ---- labels last, on top ---- */
    var below = fw(13, 7, 16), sideOff = fw(19, 10, 24);

    if (kind === 'sum') {
      if (step >= 0) { var p1 = lerp(A, B, 0.30); label(g, p1.x, p1.y + below + TS(20) * 0.5, 'u', 20); }
      if (step >= 1) {
        var nv = rnorm(B, C), pv = lerp(B, C, 0.40);
        label(g, pv.x + nv.x * sideOff, pv.y + nv.y * sideOff, 'v', 20);
      }
      if (step >= 3) {                                 // offset perpendicular, clear of the crossing
        var nd = rnorm(C, A), pd = lerp(A, C, 0.33);
        var o = fw(20, 11, 26);
        label(g, pd.x + nd.x * o, pd.y + nd.y * o, 'u + v', 22);
      }
    } else {
      if (step >= 0) { var q1 = lerp(D, C, 0.40); label(g, q1.x, q1.y - below - TS(20) * 0.5, 'u', 20); }
      if (step >= 1) {
        var nw = rnorm(C, B), pw = lerp(C, B, 0.68);
        label(g, pw.x + nw.x * sideOff, pw.y + nw.y * sideOff, '−v', 20);
      }
      if (step >= 2) { var q2 = lerp(A, B, 0.33); label(g, q2.x, q2.y + below + TS(20) * 0.5, 'u', 20); }
      if (step >= 3) {
        var ne = rnorm(D, B), pe = lerp(D, B, 0.32);
        var o2 = fw(18, 10, 24);
        label(g, pe.x + ne.x * o2, pe.y + ne.y * o2, 'u − v', 22);
      }
    }
  }

  function render() {
    root.clear();
    var ap = activePanel();
    for (var i = 0; i < panels.length; i++) drawPanel(panels[i], ap);
  }

  /* ---------- responsive layout ---------- */
  function innerSize() {
    var st = getComputedStyle(container);
    var px = (parseFloat(st.paddingLeft) || 0) + (parseFloat(st.paddingRight) || 0);
    var py = (parseFloat(st.paddingTop) || 0) + (parseFloat(st.paddingBottom) || 0);
    return { w: Math.max(80, container.clientWidth - px), h: Math.max(80, container.clientHeight - py) };
  }

  function layout(sz) {
    sz = sz || innerSize();
    var aspect = sz.w / sz.h;
    var mL = 42, mT = 44, mB = 44, VBW, VBH;

    if (aspect >= 0.85) {                       // side-by-side, as in the printed figure
      var gapX = 76;
      panels[0].A = { x: mL, y: mT + SH };
      panels[1].A = { x: mL + SW + gapX, y: mT + SH };
      VBW = mL * 2 + SW * 2 + gapX;
      VBH = mT + SH + mB;
    } else {                                    // only for a very tall, narrow frame
      var gapY = 80;
      panels[0].A = { x: mL, y: mT + SH };
      panels[1].A = { x: mL, y: mT + SH + gapY + SH };
      VBW = mL * 2 + SW;
      VBH = mT + 2 * SH + gapY + mB;
    }

    draw.viewbox(0, 0, VBW, VBH);
    s = Math.max(0.05, Math.min(sz.w / VBW, sz.h / VBH));
    render();
  }

  document.addEventListener('fig-resize', function (e) {
    layout({ w: e.detail.width || innerSize().w, h: e.detail.height || innerSize().h });
  });

  /* ---------- controls ---------- */
  function syncUI() {
    var cb = document.getElementById('operationInput');
    if (cb) cb.checked = (state.op === 'sub');
    var sv = document.getElementById('constructionStepVal');
    if (sv) sv.textContent = STEPNAMES[state.step];
  }

  function setNarration(txt) {
    var n = document.getElementById('demoNarration');
    if (n) n.textContent = txt;
  }

  window.toggle_operation = function (on) {
    state.op = on ? 'sub' : 'add';
    state.selected = null; state.focus = null; state.guided = true;
    demoIdx = -1;
    syncUI(); render();
    setNarration(on
      ? 'v is reversed into −v: same parallelogram, same u, but the resultant is now the descending diagonal u − v.'
      : 'v points up-right again: the resultant is the rising diagonal u + v.');
  };

  window.trigger_constructionStep = function () {
    state.guided = true; state.selected = null;
    state.step = (state.step + 1) % 4;
    demoIdx = -1;
    syncUI(); render();
    var msgs = [
      'Only u is drawn from the common tail.',
      'The second vector is attached head-to-tail at the head of u.',
      'Copies of the two vectors close the parallelogram — both routes end at the same corner.',
      'The diagonal from the common tail is the resultant.'
    ];
    setNarration(msgs[state.step]);
  };

  window.trigger_reset = function () { applyStep(0); };

  /* ---------- demo player ---------- */
  var steps = [
    {
      t: 'Textbook view',
      n: 'Both parallelograms as printed: the left diagonal is the sum u + v, the right diagonal is the difference u − v. Click a diagonal, or step through the construction.',
      s: { guided: false, op: 'add', step: 3 }
    },
    {
      t: 'Start with u',
      n: 'A single vector u is drawn from the common tail along the bottom edge, orange arrowhead pointing right. Nothing else exists yet.',
      s: { guided: true, op: 'add', step: 0 }
    },
    {
      t: 'Attach v head to tail',
      n: 'v is placed with its tail at the head of u, slanting up and to the right. The two vectors now form a bent path from the common tail.',
      s: { guided: true, op: 'add', step: 1 }
    },
    {
      t: 'Close the parallelogram',
      n: 'Copies of u and v complete the figure, so the same endpoint is reached by going u-then-v or v-then-u.',
      s: { guided: true, op: 'add', step: 2 }
    },
    {
      t: 'The sum is the long diagonal',
      n: 'The diagonal from the common tail to the opposite corner is highlighted in orange and labeled u + v.',
      s: { guided: true, op: 'add', step: 3 }
    },
    {
      t: 'Reverse v into −v',
      n: 'Flipping the toggle turns v around: the arrowhead on the slanted edge now points down and to the right, labeled −v (the dashed ghost shows the old v), while u is unchanged.',
      s: { guided: true, op: 'sub', step: 1 }
    },
    {
      t: 'The difference is the other diagonal',
      n: 'Head-to-tail with −v, the resultant becomes the descending diagonal labeled u − v — the same parallelogram, the other diagonal.',
      s: { guided: true, op: 'sub', step: 3 }
    }
  ];
  var demoIdx = 0;

  function applyStep(i) {
    demoIdx = i;
    var st = steps[i];
    state.guided = st.s.guided; state.op = st.s.op; state.step = st.s.step;
    state.selected = null; state.focus = null;
    syncUI(); render(); setNarration(st.n);
    var lbl = document.getElementById('stepLabel');
    if (lbl) lbl.textContent = i + ' / ' + (steps.length - 1) + ' · ' + st.t;
  }

  window.nextStep = function () { applyStep(Math.min(steps.length - 1, (demoIdx < 0 ? 0 : demoIdx) + 1)); };
  window.prevStep = function () { applyStep(Math.max(0, (demoIdx < 0 ? 1 : demoIdx) - 1)); };

  /* ---------- init ---------- */
  layout();
  applyStep(0);
  setTimeout(function () { layout(); applyStep(demoIdx < 0 ? 0 : demoIdx); }, 60);
  window.__markRendered();
})();
